// AI: below section was generated by an AI
// Loomx node identity and discovery: GET /loomx/node (schema loomx-node/1),
// the _loomx._tcp mDNS service and the one-shot announce after config saves.
#include "wled.h"
#include "loomx_dmx_math.h"

#ifndef WLED_PRODUCT_NAME
  #define WLED_PRODUCT_NAME "WLED"
#endif

namespace {

const char* dmxModeName(uint8_t mode) {
  switch (mode) {
    case DMX_MODE_DISABLED:         return "disabled";
    case DMX_MODE_SINGLE_RGB:       return "single_rgb";
    case DMX_MODE_SINGLE_DRGB:      return "single_drgb";
    case DMX_MODE_EFFECT:           return "effect";
    case DMX_MODE_EFFECT_W:         return "effect_w";
    case DMX_MODE_MULTIPLE_RGB:     return "multi_rgb";
    case DMX_MODE_MULTIPLE_DRGB:    return "multi_drgb";
    case DMX_MODE_MULTIPLE_RGBW:    return "multi_rgbw";
    case DMX_MODE_EFFECT_SEGMENT:   return "effect_segment";
    case DMX_MODE_EFFECT_SEGMENT_W: return "effect_segment_w";
    case DMX_MODE_PRESET:           return "preset";
    default:                        return "unknown";
  }
}

const char* ledTypeName(uint8_t type) {
  switch (type) {
    case TYPE_WS2812_RGB:    return "WS2812";
    case TYPE_WS2811_400KHZ: return "WS2811_400";
    case TYPE_SK6812_RGBW:   return "SK6812";
    case TYPE_TM1814:        return "TM1814";
    case TYPE_TM1829:        return "TM1829";
    case TYPE_UCS8903:       return "UCS8903";
    case TYPE_UCS8904:       return "UCS8904";
    case TYPE_WS2805:        return "WS2805";
    case TYPE_FW1906:        return "FW1906";
    case TYPE_SM16825:       return "SM16825";
    case TYPE_WS2801:        return "WS2801";
    case TYPE_APA102:        return "APA102";
    default:                 return "other";
  }
}

const char* colorOrderName(uint8_t order) {
  static const char* const names[] = {"GRB", "RGB", "BRG", "RBG", "BGR", "GBR"};
  order &= 0x0F;
  return order <= COL_ORDER_MAX ? names[order] : "GRB";
}

bool multiPixelMode() {
  return DMXMode == DMX_MODE_MULTIPLE_RGB || DMXMode == DMX_MODE_MULTIPLE_DRGB
      || DMXMode == DMX_MODE_MULTIPLE_RGBW;
}

loomx::DmxLayout currentLayout() {
  return loomx::dmxLayout(DMXMode == DMX_MODE_MULTIPLE_RGBW,
                          DMXMode == DMX_MODE_MULTIPLE_DRGB, DMXAddress);
}

void macWithColons(char* out, size_t size) {
  // escapedMac is 12 lowercase hex digits without separators.
  const char* hex = escapedMac.c_str();
  if (escapedMac.length() != 12) { strlcpy(out, hex, size); return; }
  snprintf(out, size, "%.2s:%.2s:%.2s:%.2s:%.2s:%.2s",
           hex, hex + 2, hex + 4, hex + 6, hex + 8, hex + 10);
}

} // namespace

void serializeLoomxNode(JsonObject root) {
  root[F("schema")] = F("loomx-node/1");
  root["id"] = escapedMac;
  char mac[18];
  macWithColons(mac, sizeof(mac));
  root[F("mac")] = mac;
  root[F("model")] = F(WLED_PRODUCT_NAME);
  root[F("name")] = serverDescription;

  JsonObject fw = root.createNestedObject(F("fw"));
  fw[F("wled")] = versionString;
#ifdef LOOMX_VERSION
  fw[F("loomx")] = F(LOOMX_VERSION);
#else
  fw[F("loomx")] = "";
#endif
#ifdef LOOMX_GIT_COMMIT
  fw[F("commit")] = F(LOOMX_GIT_COMMIT);
#else
  fw[F("commit")] = "";
#endif

  const bool ethernet = Network.isEthernet();
  const bool wifi = WiFi.status() == WL_CONNECTED;
  const size_t activeNetwork = ethernet ? 0 : selectedWiFi;
  JsonObject net = root.createNestedObject(F("net"));
  net["ip"] = Network.localIP().toString();
  net[F("mask")] = Network.subnetMask().toString();
  net[F("gw")] = Network.gatewayIP().toString();
  net[F("dhcp")] = multiWiFi.empty() || activeNetwork >= multiWiFi.size()
    || multiWiFi[activeNetwork].staticIP == (uint32_t)0U;
  net[F("link")] = ethernet ? "eth" : (wifi ? "wifi" : "none");
  net[F("rssi")] = wifi ? WiFi.RSSI() : 0;
  net[F("channel")] = wifi ? WiFi.channel() : 0;
  net[F("hostname")] = cmDNS;

  JsonObject e131 = root.createNestedObject(F("e131"));
  e131[F("enabled")] = receiveDirect && DMXMode != DMX_MODE_DISABLED;
  e131[F("multicast")] = e131Multicast;
  e131[F("port")] = e131Port;
  e131[F("startUniverse")] = e131Universe;
  e131[F("startAddress")] = DMXAddress;
  e131[F("mode")] = dmxModeName(DMXMode);
  e131[F("maxUniverses")] = E131_MAX_UNIVERSE_COUNT;

  const bool multi = multiPixelMode();
  const loomx::DmxLayout layout = currentLayout();
  JsonArray outputs = root.createNestedArray(F("outputs"));
  unsigned index = 0;
  for (size_t b = 0; b < BusManager::getNumBusses(); b++) {
    const Bus* bus = BusManager::getBus(b);
    if (!bus || bus->isVirtual()) continue;
    JsonObject out = outputs.createNestedObject();
    out[F("index")] = index++;
    uint8_t pins[OUTPUT_MAX_PINS] = {255, 255, 255, 255, 255};
    bus->getPins(pins);
    out[F("pin")] = pins[0];
    const unsigned len = bus->getLength();
    const unsigned start = bus->getStart();
    out[F("len")] = len;
#ifdef LOOMX_MAX_LEDS_PER_OUTPUT
    out[F("maxLen")] = LOOMX_MAX_LEDS_PER_OUTPUT;
#else
    out[F("maxLen")] = MAX_LEDS_PER_BUS;
#endif
    out[F("type")] = ledTypeName(bus->getType());
    out[F("order")] = colorOrderName(bus->getColorOrder());
    out[F("startPixel")] = start;
    if (multi && len > 0) {
      const loomx::DmxAddress first = loomx::pixelAddress(layout, e131Universe, DMXAddress, start);
      const loomx::DmxAddress last = loomx::pixelAddress(layout, e131Universe, DMXAddress, start + len - 1);
      out[F("universe")] = first.universe;
      out[F("dmxChannel")] = first.channel;
      out[F("endUniverse")] = last.universe;
      out[F("endDmxChannel")] = last.channel + layout.channelsPerLed - 1;
    } else {
      out[F("universe")] = e131Universe;
      out[F("dmxChannel")] = DMXAddress;
      out[F("endUniverse")] = e131Universe;
      out[F("endDmxChannel")] = DMXAddress;
    }
  }

  const unsigned total = strip.getLengthTotal();
  root[F("totalPixels")] = total;
  root[F("universeCount")] = multi ? loomx::universeCount(layout, total) : 1;
  root[F("configRev")] = loomxConfigRev;
  root[F("uptime")] = millis() / 1000;
  root[F("freeHeap")] = getFreeHeapSize();
}

static void loomxSetMdnsTxt() {
  char value[12];
  MDNS.addServiceTxt("loomx", "tcp", "id", escapedMac.c_str());
  MDNS.addServiceTxt("loomx", "tcp", "model", WLED_PRODUCT_NAME);
#ifdef LOOMX_VERSION
  MDNS.addServiceTxt("loomx", "tcp", "ver", LOOMX_VERSION);
#else
  MDNS.addServiceTxt("loomx", "tcp", "ver", versionString);
#endif
  snprintf(value, sizeof(value), "%u", (unsigned)e131Universe);
  MDNS.addServiceTxt("loomx", "tcp", "uni", (const char*)value);
  snprintf(value, sizeof(value), "%lu", (unsigned long)loomxConfigRev);
  MDNS.addServiceTxt("loomx", "tcp", "rev", (const char*)value);
}

void loomxBeginMdns() {
  MDNS.addService("loomx", "tcp", 80);
  loomxSetMdnsTxt();
}

void loomxHandleAnnounce() {
  if (!loomxAnnouncePending || !interfacesInited) return;
  loomxAnnouncePending = false;
  // One-shot even when periodic node broadcasts are off, so Sense/Form
  // refresh right after a configuration change.
  sendSysInfoUDP();
  if (strlen(cmDNS) > 0) loomxSetMdnsTxt();
}
// AI: end
